class ProfileRow extends DataClass implements Insertable<ProfileRow> {
  /// Always 1; the check keeps the table to a single row.
  final int id;

  /// Paise.
  final int monthlyIncomeMinor;
  final String homeCurrency;
  const ProfileRow({
    required this.id,
    required this.monthlyIncomeMinor,
    required this.homeCurrency,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['monthly_income_minor'] = Variable<int>(monthlyIncomeMinor);
    map['home_currency'] = Variable<String>(homeCurrency);
    return map;
  }

  ProfilesCompanion toCompanion(bool nullToAbsent) {
    return ProfilesCompanion(
      id: Value(id),
      monthlyIncomeMinor: Value(monthlyIncomeMinor),
      homeCurrency: Value(homeCurrency),
    );
  }

  factory ProfileRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ProfileRow(
      id: serializer.fromJson<int>(json['id']),
      monthlyIncomeMinor: serializer.fromJson<int>(json['monthlyIncomeMinor']),
      homeCurrency: serializer.fromJson<String>(json['homeCurrency']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'monthlyIncomeMinor': serializer.toJson<int>(monthlyIncomeMinor),
      'homeCurrency': serializer.toJson<String>(homeCurrency),
    };
  }

  ProfileRow copyWith({
    int? id,
    int? monthlyIncomeMinor,
    String? homeCurrency,
  }) => ProfileRow(
    id: id ?? this.id,
    monthlyIncomeMinor: monthlyIncomeMinor ?? this.monthlyIncomeMinor,
    homeCurrency: homeCurrency ?? this.homeCurrency,
  );
  ProfileRow copyWithCompanion(ProfilesCompanion data) {
    return ProfileRow(
      id: data.id.present ? data.id.value : this.id,
      monthlyIncomeMinor: data.monthlyIncomeMinor.present
          ? data.monthlyIncomeMinor.value
          : this.monthlyIncomeMinor,
      homeCurrency: data.homeCurrency.present
          ? data.homeCurrency.value
          : this.homeCurrency,
    );
  }

  @override
  String toString() {
    return (StringBuffer('ProfileRow(')
          ..write('id: $id, ')
          ..write('monthlyIncomeMinor: $monthlyIncomeMinor, ')
          ..write('homeCurrency: $homeCurrency')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(id, monthlyIncomeMinor, homeCurrency);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is ProfileRow &&
          other.id == this.id &&
          other.monthlyIncomeMinor == this.monthlyIncomeMinor &&
          other.homeCurrency == this.homeCurrency);
}

class ProfilesCompanion extends UpdateCompanion<ProfileRow> {
  final Value<int> id;
  final Value<int> monthlyIncomeMinor;
  final Value<String> homeCurrency;
  const ProfilesCompanion({
    this.id = const Value.absent(),
    this.monthlyIncomeMinor = const Value.absent(),
    this.homeCurrency = const Value.absent(),
  });
  ProfilesCompanion.insert({
    this.id = const Value.absent(),
    required int monthlyIncomeMinor,
    this.homeCurrency = const Value.absent(),
  }) : monthlyIncomeMinor = Value(monthlyIncomeMinor);
  static Insertable<ProfileRow> custom({
    Expression<int>? id,
    Expression<int>? monthlyIncomeMinor,
    Expression<String>? homeCurrency,
  }) {
    return RawValuesInsertable({
      if (id != null) 'id': id,
      if (monthlyIncomeMinor != null)
        'monthly_income_minor': monthlyIncomeMinor,
      if (homeCurrency != null) 'home_currency': homeCurrency,
    });
  }

  ProfilesCompanion copyWith({
    Value<int>? id,
    Value<int>? monthlyIncomeMinor,
    Value<String>? homeCurrency,
  }) {
    return ProfilesCompanion(
      id: id ?? this.id,
      monthlyIncomeMinor: monthlyIncomeMinor ?? this.monthlyIncomeMinor,
      homeCurrency: homeCurrency ?? this.homeCurrency,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<int>(id.value);
    }
    if (monthlyIncomeMinor.present) {
      map['monthly_income_minor'] = Variable<int>(monthlyIncomeMinor.value);
    }
    if (homeCurrency.present) {
      map['home_currency'] = Variable<String>(homeCurrency.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('ProfilesCompanion(')
          ..write('id: $id, ')
          ..write('monthlyIncomeMinor: $monthlyIncomeMinor, ')
          ..write('homeCurrency: $homeCurrency')
          ..write(')'))
        .toString();
  }
}

